export type PortHoverShift = {
    held: boolean;
    pointer: { id: number; x: number; y: number } | null;
};

export function initialPortHoverShift(): PortHoverShift {
    return { held: false, pointer: null };
}

export function keyboardPortHoverShift(state: PortHoverShift, held: boolean): PortHoverShift {
    return state.held === held ? state : { ...state, held };
}

export function pointerPortHoverShift(state: PortHoverShift,
    event: { type: string; pointerId: number; clientX: number; clientY: number; shiftKey: boolean }): PortHoverShift {
    // Enter/leave events can be generated by replacing the element under a
    // stationary pointer. They are not evidence that the modifier changed.
    if (event.type !== "pointermove" && event.type !== "pointerdown" && event.type !== "pointerup") return state;
    const previous = state.pointer;
    if (event.type === "pointermove" && previous?.id === event.pointerId
        && previous.x === event.clientX && previous.y === event.clientY) return state;
    return { held: event.shiftKey, pointer: { id: event.pointerId, x: event.clientX, y: event.clientY } };
}
